NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Daniel'

CHAPTERS = {
    1: {
        1: 'V tretjem letu kraljevanja Judovega kralja Jojakíma je prišel babilonski kralj Nebukadnezar iz Babilona do Jeruzalema in ga oblegal.',
        2: 'Gospod je Judovega kralja Jojakíma izročil v njegovo roko, z delom posod iz Božje hiše, ki jih je odnesel v deželo Šinár, k hiši svojega Boga in posode je prinesel v zakladno hišo svojega boga.',
        3: 'Kralj je spregovoril Ašpenázu, gospodarju svojih evnuhov, da naj privede nekatere izmed Izraelovih otrok, izmed kraljevega potomstva in izmed princev,',
        4: 'otroke, na katerih ni bilo madeža, temveč lepega videza in spretne v vsej modrosti in bistroumne v spoznanju in razumevanju znanosti in takšne, ki imajo v sebi zmožnost stati v kraljevi palači in ki bi jih lahko učili znanja in jezika Kaldejcev.',
        5: 'Kralj jim je določil dnevno preskrbo kraljeve hrane in od vina, ki ga je pil. Tako jih je hranil tri leta, da bi ob njihovem izteku lahko stali pred kraljem.',
        6: 'Torej med temi so bili od Judovih otrok Daniel, Hananjá, Mišaél in Azarjá,',
        7: 'ki jim je princ evnuhov dal imena, kajti Danielu je dal ime Beltšacár, Hananjáju Šadráh, Mišaélu Mešáh in Azarjáju Abéd Negó.',
        8: 'Toda Daniel se je v svojem srcu namenil, da se ne bi omadeževal z deležem kraljeve hrane niti z vinom, ki ga je ta pil, zatorej je od princa evnuhov prosil, da se mu ne bi bilo treba omadeževati.',
        9: 'Torej Bog je Daniela privedel v naklonjenost in nežno prijaznost s princem evnuhov.',
        10: 'Princ evnuhov je Danielu rekel: »Bojim se svojega gospoda kralja, ki vam je določil vašo hrano in vašo pijačo, kajti zakaj bi videl vaša obličja videti slabša kakor od otrok, ki so iz vaše vrste? Potem bi mene prisilili ogrožati mojo glavo kralju.«',
        11: '§ Potem je Daniel rekel Melzarju, ki ga je princ evnuhov postavil nad Daniela, Hananjája, Mišaéla in Azarjája:',
        12: '»Potrdi svojim služabnikom, rotim te, deset dni, in naj nam dajo za jesti rastlinsko hrano in vodo za pitje.',
        13: 'Potem naj bodo naša obličja ogledana pred teboj in obličje otrok, ki jedo od deleža kraljeve hrane, in kakor vidiš [tako] postopaj s svojimi služabniki.«',
        14: 'Tako se je ta strinjal z njimi v tej zadevi in jim potrdil deset dni.',
        15: 'Ob koncu desetih dni so bila njihova obličja videti svetlejša in obilnejša v mesu kakor od vseh otrok, ki so jedli od deleža kraljeve hrane.',
        16: '§ Potem je Melzar odvzel delež njihove hrane in vino, ki naj bi ga pili in jim dajal rastlinsko hrano.',
        17: 'Glede teh štirih otrok, jim je Bog dal znanje in spretnost v vsem učenju in modrosti. Daniel je imel razumevanje o vseh videnjih in sanjah.',
        18: 'Torej ob koncu dni, o katerih je kralj rekel, da naj jih privede, jih je potem princ evnuhov privedel pred Nebukadnezarja.',
        19: 'Kralj se je z njimi pogovarjal in med njimi vsemi ni našel nikogar podobnega Danielu, Hananjáju, Mišaélu in Azarjáju. Zato so stali pred kraljem.',
        20: 'V vseh vrstah modrosti in razumevanja, ki jih je kralj poizvedel od njih, jih je našel desetkrat boljše od vseh čarovnikov in astrologov, ki so bili v vsem njegovem območju.',
        21: 'Daniel je ostal celó do prvega leta kralja Kira.',
    },
    2: {
        1: 'V drugem letu kraljevanja Nebukadnezarja je Nebukadnezar sanjal sanje, s čimer je bil njegov duh vznemirjen in njegovo spanje se je ločilo od njega.',
        2: 'Potem je kralj zapovedal, da pokličejo čarovnike, astrologe, čarodeje in Kaldejce, da kralju razodenejo njegove sanje. Tako so prišli in stali pred kraljem.',
        3: 'Kralj jim je rekel: »Sanjal sem sanje in moj duh je bil vznemirjen, da bi razumel sanje.«',
        4: 'Potem so Kaldejci spregovorili kralju po sirsko: »Oh kralj, živi na veke. Povej svojim služabnikom sanje, mi pa bomo pokazali pomen.«',
        5: 'Kralj je odgovoril in Kaldejcem rekel: »Ta stvar je odšla od mene. Če mi ne boste razložili sanj, z njihovo razlago, boste razrezani na koščke, vaše hiše pa bodo narejene za gnojišče.',
        6: 'Toda če mi boste pokazali sanje in njihov pomen, boste od mene prejeli darila in nagrade in veliko čast. Zatorej mi razodenite sanje in njihov pomen.«',
        7: 'Ponovno so odgovorili in rekli: »Naj kralj pove svojim služabnikom sanje, mi pa bomo pokazali njihov pomen.«',
        8: 'Kralj je odgovoril in rekel: »Zagotovo vem, da hočete pridobiti čas, ker ste videli, da je stvar odšla od mene.',
        9: 'Toda če mi ne boste pokazali sanj, je za vas samo en odlok, kajti pripravili ste lažnive in izprijene besede, da jih govorite pred menoj, dokler čas ne bo spremenjen. Zato mi povejte sanje in vedel bom, da mi lahko pokažete njihovo razlago.«',
        10: 'Kaldejci so pred kraljem odgovorili in rekli: »Na zemlji ni človeka, ki lahko pokaže kraljevo zadevo. Zato tam ni kralja, gospodarja niti vladarja, ki bi zahteval takšne besede pri kateremkoli čarovniku ali astrologu ali Kaldejcu.',
        11: 'To je redka stvar, ki jo kralj zahteva in nikogar drugega ni, ki lahko to razodene pred kraljem, razen bogov, katerih prebivališče ni z mesom.«',
        12: 'Zaradi tega razloga je bil kralj jezen in zelo besen in ukazal, da uničijo vse modre babilonske može.',
        13: 'Odlok je odšel naprej, da bodo modri možje umorjeni, in iskali so Daniela in njegove tovariše, da bi bili umorjeni.',
        14: 'Potem je Daniel z nasvetom in preudarnostjo odgovoril Arjóhu, poveljniku kraljeve straže, ki je odšel, da umori modre babilonske može.',
        15: 'Odgovoril je in kraljevemu poveljniku Arjóhu rekel: »Zakaj je kraljevi odlok tako nagel?« Potem je Arjóh stvar razložil Danielu.',
        16: 'Potem je Daniel vstopil in želel od kralja, da naj mu da čas in da bo on kralju pokazal razlago.',
        17: 'Potem je Daniel odšel k svoji hiši in dal stvar spoznati Hananjáju, Mišaélu in Azarjáju, svojim družabnikom,',
        18: 'da bi glede te skrivnosti želeli milosti od Boga nebes; da se Daniel in njegovi tovariši ne bi pogubili z ostalimi modrimi babilonskimi možmi.',
        19: 'Potem je bila Danielu skrivnost razodeta v nočnem videnju. Potem je Daniel blagoslovil Boga nebes.',
        20: 'Daniel je odgovoril in rekel: »Blagoslovljeno bodi ime Boga na veke vekov, kajti modrost in moč sta njegovi',
        21: 'in on spreminja čase ter obdobja. Odstranja kralje in postavlja kralje. Daje modrost modrim in spoznanje tistim, ki poznajo razumevanje.',
        22: 'Razodeva globoke in skrite stvari. Ve kaj je v temi in razsvetljenje prebiva z njim.',
        23: 'Zahvaljujem se ti in te hvalim, oh ti Bog mojih očetov, ki si mi dal modrost in moč in si mi sedaj razodel, kar smo želeli od tebe, kajti sedaj si nam pokazal kraljevo zadevo.«',
        24: 'Zato je Daniel vstopil k Arjóhu, ki mu je kralj odredil, da uniči modre babilonske može. Odšel je in mu takole rekel: »Ne uniči modrih babilonskih mož, privedi me pred kralja in kralju bom pokazal razlago.«',
        25: 'Potem je Arjóh Daniela v naglici privedel pred kralja in mu takole rekel: »Našel sem moža izmed Judovih ujetnikov, ki bo kralju dal spoznati razlago.«',
        26: 'Kralj je odgovoril in rekel Danielu, čigar ime je bilo Beltšacár: »Ali si mi zmožen pokazati sanje, ki sem jih videl in njihovo razlago?«',
        27: 'Daniel je v prisotnosti kralja odgovoril in rekel: »Skrivnosti, ki jo je kralj zahteval, modri možje, astrologi, čarovniki [in] napovedovalci usode kralju ne morejo pokazati,',
        28: 'toda Bog je v nebesih, ki razodeva skrivnosti in daje spoznati kralju Nebukadnezarju, kaj bo v zadnjih dneh. Tvoje sanje in videnja tvoje glave na tvoji postelji so ta.',
        29: 'Kar se tebe tiče, oh kralj, tvoje misli so prišle v tvoj um na tvoji postelji, kaj se bo odslej zgodilo in on, ki razodeva skrivnosti, ti daje spoznati, kaj se bo zgodilo.',
        30: 'Toda kar se mene tiče, mi ta skrivnost ni bila razodeta zaradi kakršnekoli modrosti, ki bi jo imel več kakor katerikoli živeči, temveč zaradi tistih, ki bodo dali spoznati razlago kralju in da boš lahko poznal misli svojega srca.',
        31: 'Ti, oh kralj, si videl in ogledoval veliko podobo. Ta velika podoba, katere sijaj je bil odličen, je stala pred teboj in njena oblika je bila strašna.',
        32: 'Glava te podobe je bila iz čistega zlata, njene prsi in njeni lakti iz srebra, njen trebuh in njena stegna iz brona,',
        33: 'njene noge iz železa, njena stopala deloma iz železa, deloma pa iz ila.',
        34: 'Gledal si, dokler ni bil brez rok izklesan kamen, ki je zadel podobo v njena stopala, ki so bila iz železa in ila in jih zlomil na koščke.',
        35: 'Potem so bili železo, il, bron, srebro in zlato skupaj zlomljeni na koščke in postali kakor pleve na poletnem mlatišču, in veter jih je odnesel, da zanje ni bilo najti nobenega prostora. Kamen, ki je zadel podobo, pa je postal velika gora in napolnil celotno zemljo.',
        36: 'To so sanje in njihovo razlago bomo povedali pred kraljem.',
        37: 'Ti, oh kralj, si kralj kraljev, kajti Bog nebes ti je dal kraljestvo, oblast, moč in slavo.',
        38: 'Kjerkoli prebivajo človeški otroci, je v tvojo roko dal živali polja in perjad neba in te naredil vladarja nad njimi vsemi. Ti si ta glava iz zlata.',
        39: 'Za teboj pa bo vstalo drugo kraljestvo, slabše od tvojega in še eno, tretje kraljestvo iz brona, ki bo vladalo nad celotno zemljo.',
        40: 'Četrto kraljestvo bo čvrsto kakor železo. Kakor železo zlomi na koščke in podjarmi vse stvari, in kakor železo, ki zlomi vse te, [tako] bo to razbilo na koščke in poškodovalo.',
        41: 'Kakor si videl stopala in prste, delno iz lončarjevega ila in delno iz železa, bo kraljestvo razdeljeno, toda v njem bo moč železa, ker si videl železo pomešano z blatnim ilom.',
        42: 'In kakor so bili prsti stopal deloma iz železa in deloma iz ila, tako bo kraljestvo delno močno in delno zlomljeno.',
        43: 'Kakor si videl železo, pomešano z blatnim ilom, tako se bodo mešali med seboj s človeškim semenom, toda ne bodo se držali drug drugega, celó kakor železo ni pomešano z ilom.',
        44: 'V dneh teh kraljev bo Bog nebes vzpostavil kraljestvo, ki ne bo nikoli uničeno. In kraljestvo ne bo ostalo drugemu ljudstvu, temveč bo zlomilo na koščke in požrlo vsa ta kraljestva, sámo pa bo obstalo na veke.',
        45: 'Ker si videl, da je bil kamen brez rok izklesan iz gore in da je ta zlomil na koščke železo, bron, ilo, srebro in zlato; véliki Bog je dal spoznati kralju, kaj se bo odslej zgodilo. Sanje so zanesljive in njihova razlaga nedvoumna.«',
        46: 'Potem je kralj Nebukadnezar padel na svoj obraz, oboževal Daniela in zapovedal, da mu morajo darovati daritev in prijetne dišave.',
        47: 'Kralj je Danielu odgovoril in rekel: »Resnično je to, da je vaš Bog Bog bogov in gospod kraljev in [ta], ki razodeva skrivnosti, glede na to, da si lahko razodel to skrivnost.«',
        48: 'Potem je kralj Daniela naredil za velikega moža in mu dal mnoga sijajna darila in ga naredil vladarja nad celotno provinco Babilon in glavnega izmed voditeljev nad vsemi modrimi možmi Babilona.',
        49: 'Potem je Daniel prosil kralja in ta je postavil Šadráha, Mešáha in Abéd Negója nad zadeve babilonske province, toda Daniel je sedel pri kraljevih velikih vratih.',
    },
    3: {
        1: 'Kralj Nebukadnezar je naredil podobo iz zlata, katere višina je bila šestdeset komolcev, njena širina pa šest komolcev. Postavil jo je na ravnini Dura v provinci Babilon.',
        2: 'Potem je kralj Nebukadnezar poslal, da zbere skupaj prince, voditelje in poveljnike, sodnike, zakladnike, svetovalce, šerife in vse vladarje provinc, da pridejo k posvetitvi podobe, ki jo je postavil kralj Nebukadnezar.',
        3: 'Potem so bili princi, voditelji in poveljniki, sodniki, zakladniki, svetovalci, šerifi in vsi vladarji provinc zbrani skupaj k posvetitvi podobe, ki jo je postavil kralj Nebukadnezar in stali so pred podobo, ki jo je postavil Nebukadnezar.',
        4: 'Potem je glasnik naglas zavpil: »Vam je to zapovedano, oh ljudstvo, narodi in jeziki,',
        5: 'da kadar zaslišite zvok kornéta, flavte, harfe, pozavne, plunke, citer in vseh vrst glasbe, padite dol in obožujte zlato podobo, ki jo je postavil kralj Nebukadnezar.',
        6: 'Kdorkoli ne pade dol in ne obožuje, bo isto uro vržen v sredo goreče ognjene talilne peči.«',
        7: 'Zatorej ob tistem času, ko je vse ljudstvo zaslišalo zvok kornéta, flavte, harfe, pozavne, plunke in vseh vrst glasbe, so vsa ljudstva, narodi in jeziki padli dol in oboževali zlato podobo, ki jo je postavil kralj Nebukadnezar.',
        8: 'Zaradi česar so se ob tistem času približali neki Kaldejci in obtožili Jude.',
        9: 'Spregovorili so in rekli kralju Nebukadnezarju: »Oh kralj, živi na veke.',
        10: 'Ti, oh kralj, si izdal odlok, da naj vsak človek, ki bo zaslišal glas kornéta, flavte, harfe, pozavne, plunke in citer in vseh vrst glasbe, pade dol in obožuje zlato podobo.',
        11: 'Kdorkoli pa ne pade dol in je ne obožuje, ta bo vržen v sredo goreče ognjene talilne peči.',
        12: 'Tam so nekateri Judje, ki si jih postavil nad zadeve babilonske province: Šadráh, Mešáh in Abéd Negó. Ti možje, oh kralj, te niso upoštevali. Ne služijo tvojim bogovom niti ne obožujejo zlate podobe, ki si jo ti postavil.«',
        13: 'Potem je Nebukadnezar v svoji besnosti in razjarjenosti zapovedal, da privedejo Šadráha, Mešáha in Abéd Negója. Potem so te može privedli pred kralja.',
        14: 'Nebukadnezar je spregovoril in jim rekel: » Je to res, oh Šadráh, Mešáh in Abéd Negój, [da] ne služite mojim bogovom niti ne obožujete zlate podobe, ki sem jo postavil?',
        15: 'Torej če ste pripravljeni, da kadar zaslišite zvok kornéta, flavte, harfe, pozavne, plunke in citer in vse vrste glasbe, padete dol in obožujete podobo, ki sem jo naredil; dobro. Toda če je ne obožujete, boste isto uro vrženi v sredo goreče ognjene talilne peči, in kdo je tisti Bog, ki vas bo osvobodil iz mojih rok?«',
        16: 'Šadráh, Mešáh in Abéd Negó so odgovorili in kralju rekli: »Oh Nebukadnezar, mi nismo zaskrbljeni, da ti odgovorimo v tej zadevi.',
        17: 'Če bo temu tako, naš Bog, ki mu služimo, nas je zmožen osvoboditi pred gorečo ognjeno talilno pečjo in on nas bo osvobodil iz tvoje roke, oh kralj.',
        18: 'Toda če ne, bodi to znano tebi, oh kralj, da ne bomo služili tvojim bogovom niti oboževali zlate podobe, ki si jo postavil.«',
        19: 'Potem je bil Nebukadnezar poln razjarjenosti in videz njegovega obličja je bil spremenjen napram Šadráhu, Mešáhu in Abéd Negóju. Zatorej je spregovoril in zapovedal, da naj talilno peč sedemkrat bolj segrejejo, kot je bila običajno segreta.',
        20: 'Zapovedal je najmočnejšim možem, ki so bili v njegovi vojski, da zvežejo Šadráha, Mešáha in Abéd Negója in da jih vržejo v gorečo ognjeno talilno peč.',
        21: 'Potem so bili ti možje zvezani v njihovih plaščih, njihovih hlačah in njihovih klobukih in drugih njihovih oblačilih in vrženi so bili v sredo goreče ognjene talilne peči.',
        22: 'Torej, ker je bila kraljeva zapoved nujna in talilna peč izjemno vroča, je plamen ognja usmrtil tiste može, ki so vzdignili Šadráha, Mešáha in Abéd Negója.',
        23: 'Ti trije možje, Šadráh, Mešáh in Abéd Negó so zvezani padli dol v sredo goreče ognjene talilne peči.',
        24: 'Potem je bil kralj Nebukadnezar osupel, v naglici vstal in spregovoril ter svojim svetovalcem rekel: »Mar nismo v sredo ognja vrgli treh zvezanih mož?« Odgovorili so in rekli kralju: »Resnica, oh kralj.«',
        25: '§ Ta je odgovoril in rekel: »Glejte, vidim štiri razvezane može, ki hodijo v sredi ognja in nimajo nobene poškodbe, oblika četrtega pa je podobna Božjemu Sinu.«',
        26: 'Potem se je Nebukadnezar približal odprtini goreče ognjene talilne peči in spregovoril ter rekel: »Šadráh, Mešáh in Abéd Negó, vi služabniki najvišjega Boga, pojdite ven in pridite sem.« Potem so Šadráh, Mešáh in Abéd Negó prišli naprej iz srede ognja.',
        27: 'Princi, voditelji, poveljniki in kraljevi svetovalci, ki so bili zbrani skupaj, so videli te može, nad čigar telesi ogenj ni imel nobene oblasti, niti las njihove glave ni bil osmojen, niti njihovi plašči niso bili spremenjeni, niti nanje ni prešel vonj ognja.',
        28: 'Potem je Nebukadnezar spregovoril in rekel: »Blagoslovljen bodi Bog Šadráha, Mešáha in Abéd Negója, ki je poslal svojega angela in rešil svoje služabnike, ki so zaupali vanj in spremenili kraljevo besedo in predali svoja telesa, da ne bi služili niti oboževali kateregakoli boga, razen svojega lastnega Boga.',
        29: 'Zato izdajam odlok: ›Da bo vsako ljudstvo, narod in jezik, ki spregovori karkoli neprimernega zoper Boga Šadráha, Mešáha in Abéd Negója, razrezano na koščke in njihove hiše bodo narejene za gnojišče, zato ker ni drugega Boga, ki lahko reši na ta način.‹«',
        30: 'Potem je kralj povišal Šadráha, Mešáha in Abéd Negója v provinci Babilon.',
    },
    4: {
        1: 'Kralj Nebukadnezar vsem ljudstvom, narodom in jezikom, ki prebivajo po vsej zemlji: »Mir naj se vam pomnoži.',
        2: 'Zdelo se mi je dobro pokazati [preroška] znamenja in čudeže, ki jih je vzvišeni Bog izvršil napram meni.',
        3: 'Kako velika so njegova [preroška] znamenja! In kako mogočni so njegovi čudeži! Njegovo kraljestvo je večno kraljestvo in njegovo gospostvo je od roda do roda.',
        4: 'Jaz, Nebukadnezar, sem bil pri počitku v svoji hiši in uspešen v svoji palači.',
        5: 'Videl sem sanje, ki so me prestrašile in misli na moji postelji in videnja moje glave so me vznemirila.',
        6: 'Zatorej sem izdal odlok, da privedejo predme vse modre može Babilona, da bi mi lahko dali spoznati razlago sanj.',
        7: 'Potem so vstopili čarovniki, astrologi, Kaldejci in napovedovalci usode, in pred njimi sem jim povedal sanje, toda niso mi dali spoznati njihove razlage.',
        8: 'Toda na koncu je prišel predme Daniel, katerega ime je bilo Beltšacár, glede na ime mojega boga in v katerem je duh svetih bogov. Pred njim sem povedal sanje, rekoč:',
        9: '›Oh Beltšacár, gospodar čarovnikov, ker vem, da je v tebi duh svetih bogov in da te nobena skrivnost ne vznemirja, mi povej videnja mojih sanj, ki sem jih videl in njihovo razlago.‹',
        10: 'Takšna so bila videnja moje glave na moji postelji. Videl sem in glej drevo [je bilo] sredi zemlje in njegova višina je bila velika.',
        11: 'Drevo je raslo in bilo močno in njegova višina je segala do neba in njegovo vidno polje do konca vse zemlje.',
        12: 'Njegovo listje je bilo lepo in njegovega sadu obilo in na njem je bilo hrane za vse. Živali polja so pod njim imele senco in perjad neba je prebivala v njegovih vejah in vse meso je bilo od njega nahranjeno.',
        13: 'Videl sem v videnjih svoje glave na svoji postelji in glej, stražar in sveti je prišel dol z neba.',
        14: 'Glasno je zavpil in rekel takole: ›Posekajte drevo in odrežite njegove veje, otresite listje in raztresite njegov sad. Naj gredo živali proč izpod njega in perjad od njegovih mladik,',
        15: 'kljub temu pa pustite štor njegovih korenin v zemlji, celo v okovu iz železa in brona, v nežni travi polja in ta naj bo omočen z roso neba in njegov delež naj bo z živalmi na zemeljski travi.',
        16: 'Naj bo njegovo srce spremenjeno od človeškega in naj mu bo dano živalsko srce, in nad njim naj mine sedem dob.',
        17: 'Ta stvar je po odloku stražarjev in zahteva po besedi svetih, z namenom, da bodo živi lahko spoznali, da Najvišji vlada v kraljestvu ljudi in ga daje komur hoče in postavi nadenj najnižjega izmed ljudi.',
        18: 'Te sanje sem jaz, kralj Nebukadnezar, videl. Torej ti, oh Beltšacár, razglasi njihovo razlago, ker vsi modri ljudje mojega kraljestva niso zmožni, da bi mi dali spoznati razlago, toda ti si zmožen, kajti duh svetih bogov je v tebi.‹«',
        19: 'Potem je bil Daniel, katerega ime je bilo Beltšacár, za eno uro osupel in njegove misli so ga vznemirile. Kralj je spregovoril in rekel: »Beltšacár, ne pusti, da bi te sanje ali njihova razlaga vznemirile.« Beltšacár je odgovoril in rekel: »Moj gospod, sanje naj bodo njim, ki te sovražijo in njihova razlaga tvojim sovražnikom.',
        20: 'Drevo, ki si ga videl, ki je raslo in je bilo močno, katerega višina je segla do neba in katerega vidno polje je po vsej zemlji,',
        21: 'katerega listje je bilo lepo in njegov sad obilen in je bilo na njem hrane za vse, pod katerim so prebivale živali polja in na čigar vejah je imela perjad neba svoje prebivališče.',
        22: 'To si ti, oh kralj, ki si zrasel in postal močan, kajti tvoja veličina je zrasla in sega do neba in tvoje gospostvo do konca zemlje.',
        23: 'Medtem ko je kralj videl stražarja in svetega prihajati dol z neba in reči: ›Posekajte drevo in ga uničite, vendar od njega pustite v zemlji štor s koreninami, celo z okovom iz železa in brona, v nežni travi polja; in naj bo ta omočen z roso neba in njegov delež naj bo z živalmi polja, dokler nad njim ne mine sedem dob.‹',
        24: 'To je razlaga, oh kralj in to je odlok Najvišjega, ki je prišel nad mojega gospoda kralja,',
        25: 'da te bodo pregnali od ljudi in tvoje prebivališče bo z živalmi polja in pripravili te bodo, da boš jedel travo kakor voli in močili te bodo z roso neba in sedem dob bo prešlo nad teboj, dokler ne spoznaš, da Najvišji vlada v kraljestvu ljudi in ga daje komurkoli on hoče.',
        26: 'Zapovedali so, da pustijo štor od drevesnih korenin; tvoje kraljestvo bo zagotovo pripadlo tebi, potem ko boš spoznal, da nebesa vladajo.',
        27: '§ Zatorej, oh kralj, naj ti bo moj nasvet sprejemljiv in svoje grehe zlomi s pravičnostjo in svoje krivičnosti z izkazovanjem usmiljenja revnim; če bi to lahko bilo podaljšanje tvoje umirjenosti.‹«',
        28: 'Vse to je prišlo nad kralja Nebukadnezarja.',
        29: 'Ob koncu dvanajstih mesecev je hodil v palači babilonskega kraljestva.',
        30: 'Kralj je spregovoril in rekel: »Ali ni to veliki Babilon, ki sem ga jaz zgradil za hišo kraljestva po moči svoje oblasti in za čast svojega veličanstva?«',
        31: 'Medtem ko je bila beseda v kraljevih ustih, je padel glas z neba, rekoč: »Oh kralj Nebukadnezar, tebi je govorjeno: ›Kraljestvo je odšlo od tebe.',
        32: 'Pregnali te bodo od ljudi in tvoje prebivališče bo z živalmi polja. Prisilili te bodo, da boš jedel travo kakor voli in sedem dob bo prešlo nad teboj, dokler ne spoznaš, da Najvišji vlada v kraljestvu ljudi in ga daje komurkoli on hoče.‹«',
        33: 'To isto uro je bila stvar nad Nebukadnezarjem izpolnjena. Pregnan je bil od ljudi, jedel travo kakor voli in njegovo telo je bilo omočeno z roso z neba, dokler njegovi lasje niso zrasli kakor orlovo perje in njegovi nohti kakor ptičji kremplji.',
        34: '»In ob koncu dni sem jaz, Nebukadnezar, povzdignil svoje oči k nebu in moje razumevanje se je vrnilo k meni in blagoslovil sem Najvišjega in hvalil in častil njega, ki živi na veke, katerega gospostvo je večno gospostvo in njegovo kraljestvo je od roda do roda.',
        35: 'Vsi prebivalci zemlje so šteti kakor nič in on dela glede na svojo voljo v vojski nebes in med prebivalci zemlje, in nihče ne more zadržati njegove roke ali mu reči: ›Kaj počneš?‹',
        36: 'Ob istem času se je moj razum vrnil k meni in zaradi slave mojega kraljestva sta se moja čast in moj sijaj vrnila k meni in moji svetovalci in moji velikaši so me poiskali, jaz pa sem bil utrjen v svojem kraljestvu in dodano mi je bilo odlično veličanstvo.',
        37: 'Sedaj jaz, Nebukadnezar, hvalim, povzdigujem in častim Kralja nebes. Vsa njegova dela so resnica in njegove poti sodba, tiste pa, ki hodijo v ponosu, je zmožen ponižati.‹«',
    },
    5: {
        1: 'Kralj Belšacár je priredil veliko zabavo svojim tisoč velikašem in pil vino pred tisočimi.',
        2: 'Medtem ko je Belšacár okušal vino, je zapovedal, da prinesejo zlate in srebrne posode, ki jih je njegov oče Nebukadnezar odnesel iz templja, ki je bil v Jeruzalemu, da bi kralj in njegovi princi, njegove žene in njegove priležnice lahko pili iz njih.',
        3: 'Potem so prinesli zlate posode, ki so bile odnesene iz templja Božje hiše, ki je bila v Jeruzalemu; in kralj, njegovi princi, njegove žene in njegove priležnice so pili iz njih.',
        4: 'Pili so vino in hvalili bogove iz zlata in iz srebra, iz brona, iz železa, iz lesa in iz kamna.',
        5: 'V isti uri so prišli prsti človeške roke in pisali nasproti svečniku na zidnem ometu kraljeve palače, in kralj je zagledal del roke, ki je pisala.',
        6: 'Potem je bilo kraljevo obličje spremenjeno in njegove misli so ga vznemirile, tako da so bili sklepi njegovih ledij mlahavi in njegova kolena so udarjala druga ob drugo.',
        7: 'Kralj je glasno zaklical, da pripeljejo astrologe, Kaldejce in napovedovalce usode. In kralj je spregovoril in rekel modrim možem iz Babilona: »Kdorkoli bo prebral to pisanje in mi pokazal njegovo razlago, bo oblečen v škrlat in okoli svojega vratu bo imel verižico iz zlata in bo tretji vladar v kraljestvu.«',
        8: 'Potem so vstopili vsi kraljevi modri možje, toda niso mogli prebrati pisanja niti kralju razglasiti njegove razlage.',
        9: 'Potem je bil kralj Belšacár silno vznemirjen in njegovo obličje na njem je bilo spremenjeno in njegovi velikaši so bili osupli.',
        10: 'Torej kraljica je zaradi razloga besed kralja in njegovih velikašev prišla v hišo gostije in kraljica je spregovorila ter rekla: »Oh kralj, živi na veke. Naj te tvoje misli ne vznemirjajo niti naj tvoje obličje ne bo spremenjeno.',
        11: 'V tvojem kraljestvu je mož, v katerem je duh svetih bogov in v dneh tvojega očeta je bilo v njem najti razsvetljenje, razumevanje in modrost, podobno modrosti bogov; ki ga je kralj Nebukadnezar, tvoj oče, kralj, pravim, tvoj oče, postavil za gospodarja čarovnikov, astrologov, Kaldejcev in napovedovalcev usode;',
        12: 'ker se je v tem istem Danielu, ki ga je kralj poimenoval Beltšacár, našel odličen duh, spoznanje, razumevanje sanj, naznanjanje težkih razsodb in razreševanje dvomov. Naj bo torej Daniel poklican in pokazal bo razlago.«',
        13: 'Potem je bil Daniel priveden pred kralja. In kralj je spregovoril ter Danielu rekel: » Ali si ti tisti Daniel, ki si izmed otrok Judovega ujetništva, ki jih je kralj, moj oče, privedel iz Judeje?',
        14: 'O tebi sem slišal celo, da je v tebi duh bogov in da je v tebi najti razsvetljenje, razumevanje in odlično modrost.',
        15: 'Sedaj so bili predme privedeni modri možje, astrologi, da bi prebrali to pisanje in mi dali spoznati njegovo razlago, toda niso mogli pokazati razlage stvari.',
        16: 'O tebi pa sem slišal, da lahko daješ razlage in razrešuješ dvome. Torej če lahko prebereš pisanje in mi razglasiš njegov pomen, potem boš oblečen s škrlatom in okoli svojega vratu boš imel zlato verižico in boš tretji vladar v kraljestvu.«',
        17: 'Potem je Daniel odgovoril in pred kraljem rekel: »Naj tvoja darila [ostanejo] tebi in svoje nagrade daj drugemu; kljub temu bom kralju prebral pisanje in mu dal spoznati razlago.',
        18: 'Ti, oh kralj. Najvišji Bog je dal tvojemu očetu Nebukadnezarju kraljestvo, veličanstvo, slavo in čast.',
        19: 'Zaradi veličanstva, ki mu ga je on dal, so vsa ljudstva, narodi in jeziki trepetali in se bali pred njim. Kogar je želel, je usmrtil; in kogar je želel, je ohranil živega; in kogar je želel, je povišal; in kogar je želel, je odstavil.',
        20: 'Toda ko je bilo njegovo srce povišano in je njegov um zakrknil v ponosu, je bil odstavljen od svojega kraljevskega prestola in njegovo slavo so odvzeli od njega.',
        21: 'Pregnan je bil izmed človeških sinov in njegovo srce je bilo narejeno kakor živalsko in njegovo prebivališče je bilo z divjimi osli. Hranili so ga s travo kakor vole in njegovo telo je bilo omočeno z roso neba, dokler ni vedel, da najvišji Bog vlada v kraljestvu ljudi in da on postavlja čezenj kogarkoli on želi.',
        22: 'Ti, njegov sin, oh Belšacár, nisi ponižal svojega srca, čeprav si vse to vedel,',
        23: 'temveč si se povzdignil zoper Gospoda nebes in predte so privedli posode njegove hiše in ti in tvoji velikaši, tvoje žene in tvoje priležnice so iz njih pili vino, in hvalil si bogove iz srebra, zlata, brona, železa, lesa in kamna, ki ne vidijo niti ne slišijo niti ne vedo. Boga pa, v čigar roki je tvoj dih in katerega so vse tvoje poti, ti nisi slavil.',
        24: 'Torej je bil od njega poslan del roke, in zapisano je bilo to pisanje.',
        25: 'To je pisanje, ki je bilo zapisano: MENE, MENE, TEKEL, UPHARSIN.',
        26: 'To je razlaga stvari: MENE: ›Bog je preštel tvoje kraljestvo in ga končal.‹',
        27: 'TEKEL: ›Stehtan si bil na tehtnici in si najden pomanjkljiv.‹',
        28: 'PERES: ›Tvoje kraljestvo je razdeljeno in dano Medijcem in Perzijcem.‹«',
        29: 'Potem je Belšacár zapovedal in Daniela so oblekli s škrlatom in okoli njegovega vratu obesili verižico iz zlata in glede njega naredili razglas, da naj bi bil tretji vladar v kraljestvu.',
        30: 'V tej noči je bil Belšacár, kralj Kaldejcev, umorjen.',
        31: 'Medijec Darej je dobil kraljestvo; bil je star okoli dvainšestdeset let.',
    },
    6: {
        1: 'Dareju je ugajalo, da postavi nad kraljestvo sto dvajset princev, ki naj bi bili nad celotnim kraljestvom,',
        2: 'in nad temi tri predstojnike, od katerih je bil Daniel prvi, da bi jim princi lahko dajali obračun in kralj ne bi trpel nobene škode.',
        3: 'Potem je bil ta Daniel povišan nad predstojnike in prince, ker je bil v njem odličen duh, in kralj ga je mislil postaviti nad celotno območje.',
        4: 'Potem so predstojniki in princi iskali, da najdejo povod zoper Daniela glede kraljestva, toda niso mogli najti nobenega povoda niti krivde, ker je bil zvest niti ni bilo na njem najti nobene napake ali krivde.',
        5: 'Potem so ti možje rekli: »Nobenega razloga ne bomo našli zoper tega Daniela, razen če zoper njega najdemo to, kar se tiče postave njegovega Boga.«',
        6: 'Potem so se ti predstojniki in princi zbrali skupaj h kralju in mu rekli takole: »Kralj Darej, živi na veke.',
        7: 'Vsi predstojniki kraljestva, voditelji in princi, svetovalci in poveljniki, smo se skupaj posvetovali, da bi osnovali kraljevo pravilo in da bi naredili trden odlok, da kdorkoli bi prosil prošnjo od kateregakoli Boga ali človeka v tridesetih dneh, razen od tebe, oh kralj, bo vržen v levji brlog.',
        8: 'Torej, oh kralj, uveljavi odlok in podpiši pisanje, da to ne more biti spremenjeno, glede na postavo Medijcev in Perzijcev, ki se ne predrugači.«',
        9: 'Zatorej je kralj Darej podpisal pisanje in odlok.',
        10: 'Torej ko je Daniel izvedel, da je bilo pisanje podpisano, je odšel v svojo hišo. Pri svojih oknih v svoji sobi, odprtih proti Jeruzalemu, je trikrat na dan pokleknil na svoja kolena in molil ter se zahvaljeval pred svojim Bogom, kot je to delal poprej.',
        11: 'Potem so se ti možje zbrali in našli Daniela, kako moli in dela ponižne prošnje pred svojim Bogom.',
        12: 'Potem so prišli blizu in pred kraljem spregovorili glede kraljevega odloka: »Mar nisi podpisal odloka, da katerikoli človek, ki bo prosil prošnjo od kateregakoli Boga ali človeka, znotraj tridesetih dni, razen od tebe, oh kralj, bo vržen v levji brlog?« Kralj je odgovoril in rekel: »Stvar je resnična glede na postavo Medijcev in Perzijcev, ki se ne predrugači.«',
        13: 'Potem so odgovorili in pred kraljem rekli: »Tisti Daniel, ki je od otrok Judovega ujetništva, te ne upošteva, oh kralj niti odloka, ki si ga podpisal, temveč trikrat na dan opravlja svojo prošnjo.«',
        14: 'Potem je bil kralj, ko je slišal te besede, sam pri sebi boleče nejevoljen in je svoje srce naravnal na Daniela, da ga osvobodi, in do sončnega zahoda se je trudil, da ga osvobodi.',
        15: 'Potem so se tisti možje zbrali h kralju in kralju rekli: »Vedi, oh kralj, da je postava Medijcev in Perzijcev: ›Da noben odlok niti nobeno pravilo, ki ga je osnoval kralj, ne more biti spremenjeno.‹«',
        16: '§ Potem je kralj ukazal in privedli so Daniela ter ga vrgli v levji brlog. Kralj je torej spregovoril in Danielu rekel: »Tvoj Bog, ki mu nenehno služiš, on te bo osvobodil.«',
        17: 'Prinesen je bil kamen in položen na odprtino brloga in kralj ga je zapečatil s svojim lastnim pečatom in s pečati svojih gospodov, da se namen glede Daniela ne bi mogel spremeniti.',
        18: '§ Potem je kralj odšel v svojo palačo in noč prebil v postu niti predenj niso bili prineseni glasbeni instrumenti in njegovo spanje je odšlo od njega.',
        19: 'Potem je kralj zelo zgodaj zjutraj vstal in v naglici odšel k levjemu brlogu.',
        20: 'Ko je prišel k brlogu, je z žalostnim glasom zaklical k Danielu, in kralj je spregovoril ter Danielu rekel: »Oh Daniel, služabnik živega Boga, ali te je tvoj Bog, ki mu nenehno služiš, mogel osvoboditi pred levi?«',
        21: 'Potem je Daniel rekel kralju: »Oh kralj, živi na veke.',
        22: 'Moj Bog je poslal svojega angela in zaprl levom usta, da me niso poškodovali, ker je bila v meni najdena nedolžnost pred njim in tudi pred teboj, oh kralj, nisem storil nobene škode.«',
        23: 'Potem je bil kralj zaradi njega silno vesel in zapovedal, da naj Daniela izvlečejo iz brloga. Tako je bil Daniel vzet gor iz brloga in nobena vrsta poškodbe ni bila najdena na njem, ker je veroval v svojega Boga.',
        24: 'In kralj je zapovedal in privedli so tiste može, ki so Daniela obtožili in jih vrgli v levji brlog, njih, njihove otroke in njihove žene. Levi so imeli oblast nad njimi in vse njihove kosti so zlomili na koščke, še preden so prileteli na dno brloga.',
        25: 'Potem je kralj Darej napisal vsemu ljudstvu, narodom in jezikom, ki prebivajo na vsej zemlji: »Mir naj se vam pomnoži.',
        26: 'Naredim odlok: ›Da v vsakem gospostvu mojega kraljestva ljudje trepetajo in se bojijo pred Danielovim Bogom, kajti on je živi Bog in neomajen na veke in njegovo kraljestvo tisto, ki ne bo uničeno in njegovo gospostvo bo celo do konca.',
        27: 'On osvobaja in rešuje, dela [preroška] znamenja in čudeže v nebesih in na zemlji, ki je Daniela osvobodil pred oblastjo levov.‹«',
        28: 'Tako je ta Daniel uspeval v Darejevem kraljevanju in v kraljevanju Perzijca Kira.',
    },
    7: {
        1: 'V prvem letu babilonskega kralja Belšacárja je imel Daniel sanje in videnja svoje glave na svoji postelji. Potem je sanje zapisal in povedal povzetek stvari.',
        2: 'Daniel je spregovoril in rekel: »Videl sem v svojem videnju ponoči in glej, štirje vetrovi neba so se borili nad velikim morjem.',
        3: 'Štirje veliki zverniki so prišli iz morja, različni drug od drugega.',
        4: 'Prvi je bil podoben levu in imel je orlove peruti. Gledal sem, dokler niso bile njegove peruti izpuljene in dvignjen je bil z zemlje in primoran stati na stopalih kakor človek, in temu je bilo dano človeško srce.',
        5: 'Glej še en zvernik, drug, podoben medvedu in ta se je dvignil na eno stran in v ustih, med svojimi zobmi, je imel tri rebra. Rekli so mu takole: ›Vzdigni se, požri veliko mesa.‹',
        6: 'Potem sem zagledal in glej drug, podoben leopardu, ki je imel na svojem hrbtu štiri krila perjadi. Zvernik je imel tudi štiri glave in dano mu je bilo gospostvo.',
        7: 'Potem sem v nočnih videnjih zagledal in glej četrtega zvernika, groznega, strašnega in silno močnega. Ta je imel velike železne zobe. Požiral je in lomil na koščke in preostanek poteptal s svojimi stopali. Ta je bil različen od vseh zvernikov, ki so bili pred njim, in ta je imel deset rogov.',
        8: 'Opazoval sem rogove in glej, tam se je med njimi vzdignil drug, majhen rog, pred katerim so bili trije izmed prvih rogov izruvani s koreninami. Glej na tem rogu so bile oči, podobne očem človeka in usta, ki so govorila velike stvari.',
        9: 'Gledal sem, dokler niso bili prestoli zrušeni in se je Starodavni usedel, katerega obleka je bila bela kakor sneg in lasje njegove glave podobni čisti volni. Njegov prestol je bil podoben ognjenemu plamenu in njegova kolesa kakor goreč ogenj.',
        10: 'Goreč tok je izviral in prihajal izpred njega. Tisoči tisočev so mu služili in desettisočkrat deset tisoči so stali pred njim. Sodba je bila odrejena in knjige so bile odprte.',
        11: 'Takrat sem gledal zaradi glasu velikih besed, ki jih je rog spregovoril. Gledal sem, dokler ni bil zvernik pokončan, njegovo telo uničeno in izročeno gorečemu plamenu.',
        12: 'Glede ostalih zvernikov, njihovo gospostvo jim je bilo odvzeto. Vendar so bila njihova življenja podaljšana za obdobje in čas.',
        13: 'Videl sem v nočnih videnjih in glej, nekdo, podoben Sinu človekovemu, je prišel z oblaki neba in prišel k Starodavnemu in privedli so ga blizu predenj.',
        14: 'Dano mu je bilo gospostvo, slava in kraljestvo, da bi mu služila vsa ljudstva, narodi in jeziki. Njegovo gospostvo je večno gospostvo, ki ne bo preminilo in njegovo kraljestvo tisto, ki ne bo uničeno.',
        15: 'Jaz, Daniel, sem bil užaloščen v svojem duhu v sredi svojega telesa in videnja moje glave so me vznemirila.',
        16: 'Približal sem se k tistemu izmed njih, ki je stal poleg in ga vprašal resnico o vsem tem. Tako mi je povedal in mi dal spoznati razlago o stvareh.',
        17: 'Ti veliki zverniki, ki so štirje, so štirje kralji, ki se bodo vzdignili iz zemlje.',
        18: 'Toda Sveti Najvišjega bodo prejeli kraljestvo in kraljestvo bodo obdržali v lasti na veke, celo na veke vekov.',
        19: 'Potem sem želel vedeti resnico o četrtem zverniku, ki je bil različen od vseh ostalih, silno grozen, katerega zobje so bili iz železa in njegovi kremplji iz brona, ki je žrl, lomil na koščke in preostanek poteptal s svojimi stopali',
        20: 'in o desetih rogovih, ki so bili na njegovi glavi in o drugem, ki se je dvignil in pred katerim so trije padli. Celo o tistem rogu, ki je imel oči in usta, ki so govorila zelo velike stvari, katerega pogled je bil arogantnejši kakor od njegovih tovarišev.',
        21: 'Pogledal sem in isti rog je začel vojno s svetimi in prevladal zoper njih,',
        22: 'dokler ni prišel Starodavni in je bila sodba dana svetim Najvišjega in je prišel čas, da so sveti vzeli v last kraljestvo.',
        23: 'Tako je rekel: ›Četrti zvernik bo četrto kraljestvo na zemlji, ki bo različno od vseh kraljestev in požrlo bo celotno zemljo in jo pomendralo ter jo zlomilo na koščke.',
        24: 'Deset rogov iz tega kraljestva je deset kraljev, ki bodo vstali in drug bo vstal za njimi. Ta bo različen od prvega in podvrgel bo tri kralje.',
        25: 'Govoril bo velike besede zoper Najvišjega in izmučil bo svete Najvišjega in mislil, da spremeni čase in postave, oni pa bodo dani v njegovo roko do časa in [dveh] časov in polovice časa.',
        26: 'F Toda sodba se bo usedla in odvzeli bodo njegovo gospostvo, da použije in da ga uniči do konca.',
        27: 'Kraljestvo, gospostvo in veličina kraljestva pod celotnim nebom bo dano ljudstvu svetih Najvišjega, katerega kraljestvo je večno kraljestvo in vsa njegova gospostva mu bodo služila in ga ubogala.‹',
        28: 'Do zdaj je konec zadeve. Kar se tiče mene, Daniela, me je moje poglobljeno razmišljanje zelo vznemirilo in moje obličje na meni je bilo spremenjeno, toda zadevo sem obdržal v svojem srcu.‹«',
    },
    8: {
        1: 'V tretjem letu kraljevanja kralja Belšacárja se mi je prikazalo videnje, celo meni, Danielu, po tistem, ki se mi je prikazalo najprej.',
        2: 'Videl sem v videnju in pripetilo se je, ko sem gledal, da sem bil v [mestu] Suze, v palači, ki je v provinci Elám, in videl sem v videnju in bil sem pri reki Uláj.',
        3: 'Potem sem povzdignil svoje oči, videl in glej, tam pred reko je stal oven, ki je imel dva rogova in dva rogova sta bila visoka. Toda eden je bil višji kakor drug in višji je prišel zadnji.',
        4: 'Videl sem ovna bosti proti zahodu in proti severu in proti jugu, tako, da noben zvernik ni mogel stati pred njim niti tam ni bilo nikogar, ki bi ga lahko osvobodil iz njegove roke, temveč je počel glede na svojo voljo in postal velik.',
        5: 'Ko sem preudarjal, glej, je od zahoda prišel kozel na obličje celotne zemlje, tal pa se ni dotaknil, in kozel je imel med svojimi očmi opazen rog.',
        6: 'Ta je prišel k ovnu, ki je imel dva rogova, ki sem ga videl stati pred reko in stekel k njemu v razjarjenosti svoje moči.',
        7: 'Videl sem ga približevati se ovnu in prevzet je bil z gnevom zoper njega in udaril ovna ter zlomil dva njegova rogova. V ovnu pa ni bilo moči, da stoji pred njim, temveč ga je vrgel dol k tlom in ga poteptal, in nikogar ni bilo, ki bi mogel ovna osvoboditi iz njegove roke.',
        8: 'Zato je kozel postal zelo velik, in ko je bil močan, je bil veliki rog zlomljen in za tem so prišli gor štirje opazni, [razdeljeni] proti štirim vetrovom neba.',
        9: 'Iz enega izmed njih je prišel majhen rog, ki je postal silno velik, proti jugu in proti vzhodu in proti prijetni deželi.',
        10: 'Ta je postal velik, celó do nebeške vojske, in ta je vrgel dol nekatere izmed vojske in od zvezd k tlom in poteptal nad njimi.',
        11: 'Da, poveličeval je samega sebe, celo do princa vojske in z njim je bilo odvzeto dnevno žrtvovanje in prostor njegovega svetišča je bil vržen dol.',
        12: 'In dana mu je bila vojska zoper dnevno žrtvovanje zaradi razloga prestopka in ta je vrgel resnico dol k tlom in to izvedel in uspel.',
        13: 'Potem sem zaslišal nekega svetega govoriti in drugi sveti je rekel temu nekemu svetemu, ki je govoril: »Doklej bo videnje glede dnevnega žrtvovanja in prestopka zapuščenosti, da bosta tako svetišče kakor vojska pogažena pod stopalom?«',
        14: 'Rekel mi je: »Do dva tisoč tristo dni, potem bo svetišče očiščeno.«',
        15: 'Pripetilo se je, ko sem jaz, celó jaz, Daniel, videl videnje in si prizadeval najti pomen, potem, glej, je tam pred menoj stal kakor videz moža.',
        16: 'Zaslišal sem človeški glas med bregovoma Ulája, ki je zaklical in rekel: »Gabriel, stôri temu človeku, da razume videnje.«',
        17: 'Tako se je približal, kjer sem stal. Ko je prišel, sem bil prestrašen in padel na svoj obraz, toda rekel mi je: »Razumi, oh človeški sin, kajti videnje bo ob času konca.«',
        18: 'Torej, ko je govoril z menoj, sem bil v globokem spanju, s svojim obrazom proti tlom, toda dotaknil se me je in me postavil pokonci.',
        19: 'Rekel je: »Glej, dal ti bom spoznati kaj bo v zadnjem koncu ogorčenja, kajti ob določenem času bo konec.',
        20: 'Oven, ki si ga videl, ki je imel dva rogova, sta kraljestvi Medije in Perzije.',
        21: 'Razmršen kozel je kralj Grčije, in velik rog, ki je med njegovimi očmi, je prvi kralj.',
        22: 'Torej ta je bil zlomljen, medtem ko so štirje vstali namesto tega; štiri kraljestva bodo vstala iz naroda, toda ne v njegovi moči.',
        23: 'V zadnjem času njihovega kraljestva, ko pridejo prestopniki v polni meri, bo vstal kralj krutega obličja in razumevanja temnih razsodb.',
        24: 'Njegova moč bo mogočna, toda ne z njegovo lastno močjo. Ta bo izvrstno uničeval in uspeval bo in izvedel in uničil bo mogočnega in sveto ljudstvo.',
        25: 'Zaradi svoje strategije bo tudi povzročil, da bo prebrisanost uspevala v njegovi roki, in poveličeval se bo v svojem srcu in z mirom bo uničil mnoge. Stal bo tudi zoper Princa princev, toda zlomljen bo brez roke.',
        26: 'Videnje večera in jutra, ki je bilo povedano, je resnično. Zato zastri videnje, kajti to bo za mnoge dni.',
        27: 'Jaz, Daniel, sem bil nekaj dni slaboten in bolan. Potem sem se dvignil in opravljal kraljeva opravila, bil pa sem osupel nad videnjem, toda nihče ga ni razumel.',
    },
    9: {
        1: 'V prvem letu Dareja, sina Ahasvérja, iz rodu Medijcev, ki je bil postavljen za kralja nad območjem Kaldejcev,',
        2: 'v prvem letu njegovega kraljevanja sem jaz, Daniel, po knjigah razumel število let, o čemer je Gospodova beseda prišla preroku Jeremiju, da bo dovršil sedemdeset let v opustošenjih Jeruzalema.',
        3: 'Svoj obraz sem naravnal h Gospodu Bogu, da [ga] iščem z molitvijo, ponižnimi prošnjami, postom, vrečevino in pepelom.',
        4: 'Molil sem h Gospodu, svojemu Bogu in naredil svoje priznanje ter rekel: »Oh Gospod, velik in grozen Bog, ki ohranja zavezo in usmiljenje tistim, ki ga ljubijo in tistim, ki se držijo njegovih zapovedi.',
        5: 'Grešili smo in zagrešili krivičnost, počeli zlobno in se uprli, celo z odhajanjem od tvojih predpisov in od tvojih sodb.',
        6: 'Niti nismo prisluhnili tvojim služabnikom prerokom, ki so v tvojem imenu govorili našim kraljem, našim princem in našim očetom in vsemu ljudstvu dežele.',
        7: 'Oh Gospod, pravičnost pripada tebi, toda nam zmešnjava obrazov, kakor na ta dan; možem iz Juda in prebivalcem Jeruzalema in vsemu Izraelu, ki so blizu in ki so daleč, po vseh deželah, kamor si jih pognal zaradi njihovega prekrška, ki so ga zagrešili zoper tebe.',
        8: 'Oh Gospod, nam pripada osramotitev obrazov, našim kraljem, našim princem in našim očetom, ker smo grešili zoper tebe.',
        9: 'Gospodu, našemu Bogu, pripadajo usmiljenja in odpuščanja, čeprav smo grešili zoper njega,',
        10: 'niti se nismo pokoravali glasu Gospoda, svojega Boga, da se ravnamo po njegovih postavah, ki jih je postavil pred nami po svojih služabnikih prerokih.',
        11: 'Da, ves Izrael je prekršil pravila tvoje postave, celo z odhajanjem, da ne bi ubogali tvojega glasu. Zato je nad nas izlito prekletstvo in prisega, ki je zapisana v postavi Božjega služabnika Mojzesa, ker smo grešili zoper njega.',
        12: 'In on je potrdil svoje besede, ki jih je govoril zoper nas in zoper naše sodnike, ki so nas sodili, s tem, da je nad nas privedel veliko zlo, kajti pod celotnim nebom se ni zgodilo, kakor se je zgodilo nad Jeruzalemom.',
        13: 'Kakor je to zapisano v Mojzesovi postavi, je vse to zlo prišlo nad nas, vendar nismo opravili svoje molitve pred Gospodom, svojim Bogom, da bi se lahko obrnili od svojih krivičnosti in razumeli tvojo resnico.',
        14: 'Zato je Gospod bedel nad zlom in ga privedel nad nas, kajti Gospod, naš Bog, je pravičen v vseh svojih delih, ki jih počne, kajti nismo ubogali njegovega glasu.',
        15: 'Sedaj, oh Gospod, naš Bog, ki si svoje ljudstvo z mogočno roko privedel iz egiptovske dežele in si si pridobil ugled kakor na ta dan; grešili smo, počeli smo zlobno.',
        16: 'Oh Gospod, glede na vso tvojo pravičnost te rotim, naj bo tvoja jeza in tvoja razjarjenost obrnjena proč od tvojega mesta, Jeruzalema, tvoje svete gore, ker so zaradi naših grehov in zaradi krivičnosti naših očetov Jeruzalem in tvoje ljudstvo postali graja vsem, ki so okoli nas.',
        17: 'Zdaj torej, oh naš Bog, prisluhni molitvi svojega služabnika in njegovim ponižnim prošnjam in povzroči svojemu obrazu, da zasije nad tvojim svetiščem, ki je zapuščeno zaradi Gospoda.',
        18: 'Oh moj Bog, nagni svoje uho in prisluhni. Odpri svoje oči in glej naša opustošenja in mesto, ki je imenovano s tvojim imenom, kajti ne predstavljamo svojih ponižnih prošenj pred teboj zaradi svoje pravičnosti, temveč zaradi tvojih velikih usmiljenj.',
        19: 'Oh Gospod, prisluhni; oh Gospod, odpusti; oh Gospod, prisluhni in stôri. Ne odlašaj zaradi sebe, oh moj Bog, kajti tvoje mesto in tvoje ljudstvo se imenujeta po tvojem imenu.«',
        20: 'Medtem ko sem govoril in molil ter priznaval svoj greh in greh svojega ljudstva Izraela in predstavljal svojo ponižno prošnjo pred Gospodom, svojim Bogom, za sveto goro svojega Boga;',
        21: 'da, medtem ko sem govoril v molitvi, je celo mož Gabriel, ki sem ga videl v videnju na začetku, naglo priletel in se me dotaknil ob času večerne daritve.',
        22: 'Poučil me je, govoril z menoj in rekel: »Oh Daniel, sedaj sem prišel, da ti dam znanje in razumevanje.',
        23: 'Na začetku tvoje ponižne prošnje je prišla zapoved in prišel sem, da se ti pokažem, kajti ti si silno ljubljen, zato razumi zadevo in preudari videnje.',
        24: 'Sedemdeset tednov je določenih nad tvojim ljudstvom in nad tvojim svetim mestom, da preneha prestopek in se naredi konec grehom in se naredi pobotanje za krivičnost in da se vpelje večna pravičnost in se zapečatita videnje in prerokovanje in da se mazili Najsvetejše.',
        25: 'Vedi torej in razumi, da bo od izida zapovedi, da se obnovi in zgradi Jeruzalem, do Mesija, Princa, sedem tednov in dvainšestdeset tednov. Ulica bo ponovno zgrajena in obzidje, celo v težkih časih.',
        26: '§ Po dvainšestdesetih tednih bo Mesija usmrčen, toda ne zaradi sebe; in ljudstvo princa, ki bo prišlo, bo uničilo mesto in svetišče. Njegov konec bo s poplavo in do konca so določena vojna opustošenja.',
        27: '§ Potrdil bo to zavezo z mnogimi za en teden. In v sredi tedna bo povzročil, da bo klavna daritev in jedilna daritev prenehala in zaradi razširjanja ogabnosti bo on to opustošil, celo do použitja in to določeno bo izlito na opustošenje.«',
    },
    10: {
        1: '§ V tretjem letu perzijskega kralja Kira je bila stvar razodeta Danielu, katerega ime je bilo imenovano Beltšacár. Stvar je bila resnična, toda določeni čas je bil dolg, in razumel je stvar in imel je razumevanje videnja.',
        2: 'V tistih dneh sem jaz, Daniel, žaloval tri polne tedne.',
        3: 'Nisem jedel nobenega prijetnega kruha, niti ni prišlo v moja usta meso, niti vino, niti se sploh nisem mazilil, dokler niso bili izpolnjeni dnevi treh tednov.',
        4: '§ Na štiriindvajseti dan prvega meseca, medtem ko sem bil ob bregu velike reke, ki je Hidekel,',
        5: '§ takrat sem povzdignil svoje oči in pogledal in glej, neki mož, oblečen v platno, čigar ledja so bila opasana s finim zlatom iz Ufaza.',
        6: 'Tudi njegovo telo je bilo podobno berilu in njegov obraz kakor videz bliskanja in njegove oči kakor ognjene svetilke in njegovi lakti in njegova stopala podobna barvi zloščenega brona in glas njegovih besed podoben glasu množice.',
        7: 'Samo jaz, Daniel, sem videl videnje, kajti ljudje, ki so bili z menoj, videnja niso videli, toda nanje je padlo veliko drgetanje, tako da so zbežali, da se poskrijejo.',
        8: '§ Torej sem ostal sam in gledal to veliko videnje in v meni ni ostalo nobene moči, kajti moja ljubkost je bila v meni spremenjena v pokvarjenost in nobene moči nisem ohranil.',
        9: 'Vendar sem zaslišal glas njegovih besed. Ko sem poslušal glas njegovih besed, sem bil potem v globokem spanju na svojem obrazu in s svojim obrazom proti tlom.',
        10: 'Glej, dotaknila se me je roka, ki me je postavila na moja kolena in na dlani mojih rok.',
        11: 'Rekel mi je: »Oh Daniel, silno ljubljen mož, razumi besede, ki ti jih govorim in stoj pokončno, kajti sedaj sem poslan k tebi.« In ko mi je govoril to besedo, sem trepetajoč stal.',
        12: 'Potem mi je rekel: »Ne boj se, Daniel, kajti od prvega dne, ko si pripravil svoje srce k razumevanju in da se ponižaš pred svojim Bogom, so bile tvoje besede uslišane in prišel sem zaradi tvojih besed.',
        13: '§ Toda princ perzijskega kraljestva se mi je zoperstavljal enaindvajset dni. Toda glej, prišel je Mihael, eden izmed glavnih princev, da mi pomaga, in ostal sem tam s perzijskimi kralji.',
        14: 'Sedaj sem prišel, da ti dam razumevanje, kaj bo doletelo tvoje ljudstvo v zadnjih dneh, kajti videnje je še za mnoge dni.«',
        15: 'Ko mi je govoril takšne besede, sem pobesil svoj obraz proti tlom in postal nem.',
        16: 'Glej, nekdo podoben človeškim sinovom, se je dotaknil mojih ustnic. Potem sem odprl svoja usta in spregovoril ter rekel temu, ki je stal pred menoj: »Oh moj gospod, po videnju so se moje bridkosti obrnile k meni in nisem ohranil nobene moči.',
        17: 'Kajti kako lahko služabnik tega mojega gospoda govori s tem mojim gospodom? Kajti kar se mene tiče, nemudoma v meni ni ostalo nobene moči niti v meni ni ostalo diha.«',
        18: 'Potem je ponovno prišel in se me dotaknil nekdo, podoben videzu človeka, me okrepil',
        19: 'in rekel: »Oh silno ljubljeni mož, ne boj se. Mir ti bodi, bodi močan, da, bodi močan.« Ko mi je govoril, sem bil okrepljen in rekel [sem]: »Naj moj gospod govori, kajti okrepil si me.«',
        20: 'Potem je rekel: »Ali veš zakaj sem prišel k tebi? Sedaj se bom vrnil, da se borim s princem Perzije. Ko odidem, glej, bo prišel princ Grčije.',
        21: 'Toda pokazal ti bom to, kar je zabeleženo v pismu resnice, in tam ni nikogar, ki drži z menoj v teh stvareh, razen Mihaela, vašega princa.«',
    },
    11: {
        1: 'Tudi jaz sem v prvem letu Medijca Dareja, celó jaz, stal, da ga potrdim in okrepim.',
        2: '§ Sedaj ti bom pokazal resnico: »Glej, v Perziji bodo vstali še trije kralji, četrti pa bo mnogo bogatejši kakor oni vsi. S svojo močjo bo po svojih bogastvih vse razvnel zoper področje Grčije.',
        3: 'Vstal bo mogočen kralj, ki bo vladal z velikim gospostvom in počel glede na svojo voljo.',
        4: 'Ko bo vstal, bo njegovo kraljestvo zlomljeno in razdeljeno bo proti štirim vetrovom neba, in ne k njegovemu potomstvu niti glede na njegovo gospostvo, ki mu je vladal, kajti njegovo kraljestvo bo izpuljeno, celo za druge poleg teh.',
        5: 'Južni kralj bo močan in eden izmed njegovih princev in on bo močan nad njim in imel bo gospostvo; njegovo gospostvo bo veliko gospostvo.',
        6: '§ Ob koncu let se bosta združila skupaj, kajti kraljeva hči iz juga bo prišla k severnemu kralju, da sklene dogovor. Toda ona ne bo obdržala moči lakta niti on ne bo obstal niti njegov laket, temveč bo izdana in tisti, ki so jo privedli in tisti, ki jo je zaplodil in kdor jo je okrepil v teh časih.',
        7: 'Toda iz mladike njenih korenin bo vstal nekdo v svoji lastnini, ki bo prišel z vojsko in vstopil v trdnjavo severnega kralja in se bo spoprijel zoper njih in bo prevladal.',
        8: '§ Prav tako bo ujete odvedel v Egipt njihove bogove z njihovimi princi in z njihovimi dragocenimi posodami iz srebra in zlata, in nadaljeval bo več let kakor kralj iz severa.',
        9: 'Tako bo južni kralj prišel v svoje kraljestvo in se bo vrnil v svojo lastno deželo.',
        10: 'Toda njegova sinova bosta razvneta in bosta zbrala množico velikih sil, in nekdo bo zagotovo prišel, preplavil in šel skozi. Potem se bo vrnil in bo razvnet, celó do svoje trdnjave.',
        11: 'Južni kralj bo prevzet z gnevom in prišel bo in se boril z njim, celó s severnim kraljem, in postavil bo veliko množico, toda množica bo dana v njegovo roko.',
        12: 'In ko bo odvedel množico, bo njegovo srce povzdignjeno in podrl bo mnogo deset tisočev, toda s tem ne bo okrepljen.',
        13: 'Kajti severni kralj se bo vrnil in vzpostavil množico, večjo kakor prejšnja in zagotovo bo prišel čez določena leta z veliko vojsko in z mnogimi bogastvi.',
        14: 'V tistih časih bodo mnogi vstali zoper južnega kralja. Tudi roparji tvojega ljudstva se bodo povišali, da vzpostavijo videnje; vendar bodo padli.',
        15: 'Tako bo prišel severni kralj in nasul nasip in zavzel najbolj utrjena mesta, in orožje iz juga se ne bo zoperstavilo niti njegovo izvoljeno ljudstvo niti ne bo nobene moči, da se zoperstavi.',
        16: 'Toda tisti, ki prihaja zoper njega, bo storil glede na svojo lastno voljo in nihče ne bo obstal pred njim. Ta pa bo stal v veličastni deželi, ki bo z njegovo roko použita.',
        17: '§ Svoj obraz bo tudi naravnal, da vstopi z močjo svojega celotnega kraljestva in pokončni z njim. Tako bo storil. Dal mu bo hčer izmed žensk, kvareč jo, toda ona ne bo obstala na njegovi strani niti ne bo zanj.',
        18: 'Potem bo svoj obraz obrnil k otokom in bo mnoge zavzel, toda princ bo zaradi svoje koristi povzročil, da bo zasramovanje, ki ga je ta dajal, prenehalo. Brez njegovega lastnega zasramovanja mu bo povzročil, da se to obrne nadenj.',
        19: 'Potem bo svoj obraz obrnil proti utrdbi svoje lastne dežele, toda spotaknil se bo, padel in ne bo najden.',
        20: 'Potem bo v svoji lastnini vstal prenašalec davkov v slavi kraljestva, toda v nekaj dneh bo uničen, niti z jezo, niti v bitki.',
        21: 'V njegovi lastnini bo vstala podla oseba, ki ji ne bodo dali časti kraljestva, toda vstopil bo miroljubno in kraljestvo dosegel z laskanji.',
        22: '§ S silami poplave bodo odplavljeni izpred njega in bodo zlomljeni; da, tudi princ zaveze.',
        23: 'Potem ko z njim sklene sodelovanje, bo postopal varljivo, kajti prišel bo gor in postal močan z majhnim ljudstvom.',
        24: 'Vstopil bo miroljubno, celo na najrodovitnejše kraje province. Počel bo to, kar njegovi očetje niso storili niti očetje njihovih očetov. Mednje bo razkropil plen, oplenjeno in bogastva. Da, napovedal bo svoje naklepe zoper oporišča, celo za nekaj časa.',
        25: 'Z veliko vojsko bo razvnel svojo moč in svoj pogum zoper južnega kralja, in južni kralj bo razvnet v bitko z veliko in mogočno vojsko, toda ne bo obstal, kajti zoper njega bodo napovedali naklepe.',
        26: 'Da, tisti, ki se hranijo od deleža njegove hrane, ga bodo uničili in njegova vojska se bo razkropila. Mnogi bodo popadali umorjeni.',
        27: 'Srci obeh teh kraljev bosta počeli vragolijo in pri eni mizi bosta govorila laži. Toda to ne bo uspelo, kajti vendar bo konec ob določenem času.',
        28: 'Potem se bo vrnil v svojo deželo z velikimi bogastvi, in njegovo srce bo zoper sveto zavezo. Počel bo junaška dejanja in se vrnil v svojo lastno deželo.',
        29: 'Ob določenem času se bo vrnil in prišel proti jugu, toda ta ne bo kakor prejšnji ali kakor zadnji.',
        30: 'Kajti ladje Kitéjcev bodo prišle zoper njega. Zato bo užaloščen, se vrnil in bo ogorčen zoper sveto zavezo. Tako bo storil; torej vrnil se bo in imel posvet s tistimi, ki so zapustili sveto zavezo.',
        31: '§ Sile bodo stopile na njegovo stran in oskrunili bodo svetišče moči in odpravili bodo dnevno daritev in postavili ogabnost, ki dela opustošenje.',
        32: 'Tiste, ki zlobno ravnajo zoper zavezo, bo pokvaril z laskanji, toda ljudstvo, ki pozna svojega Boga, bo močno in delalo bo junaška dela.',
        33: 'Tisti med ljudstvom, ki razumejo, bodo poučevali mnoge, vendar bodo padali pod mečem in v plamenu, v ujetništvu in po plenjenju, mnogo dni.',
        34: 'Torej ko bodo padali, jim bo pomagano z majhno pomočjo, toda mnogi se jih bodo oklenili z laskanji.',
        35: 'Nekateri izmed tistih z razumevanjem bodo padli, da se jih preizkusi in prečisti in se jih naredi bele, celó do časa konca, ker je to še za določeni čas.',
        36: 'Kralj pa bo počel glede na svojo voljo in poviševal se bo in se poveličeval nad vsakega boga in govoril bo osupljive stvari zoper Boga bogov in uspeval bo, dokler ne bo dovršeno ogorčenje, kajti to, kar je določeno, bo storjeno.',
        37: 'Niti se ne bo oziral na Boga svojih očetov, niti na željo žensk, niti na kateregakoli boga, kajti poveličeval se bo nad vse.',
        38: 'Toda v svoji lastnini bo spoštoval boga sil, in boga, ki ga njegovi očetje niso poznali, bo častil z zlatom, srebrom, dragocenimi kamni in prijetnimi stvarmi.',
        39: '§ Tako bo storil v najmočnejših oporiščih s tujim bogom, ki ga bo priznal in narastel s slavo. Povzročil jim bo, da vladajo nad mnogimi in deželo bo razdelil zaradi dobička.',
        40: 'Ob času konca bo južni kralj pritisnil nanj in severni kralj bo prišel proti njemu kot vrtinčast veter, z bojnimi vozovi in s konjeniki in z mnogimi ladjami in vstopil bo v dežele, jih preplavil in prešel.',
        41: 'Vstopil bo tudi v veličastno deželo in mnoge dežele bodo premagane, toda te bodo pobegnile iz njegove roke, celó Edóm, Moáb in vodja Amónovih sinov.',
        42: 'Svojo roko bo iztegnil tudi nad dežele in egiptovska dežela ne bo ubežala.',
        43: 'Toda imel bo oblast nad zakladi iz zlata, srebra in nad vsemi dragocenimi egiptovskimi stvarmi in Libijci in Etiopijci bodo pri njegovih korakih.',
        44: 'Toda novice iz vzhoda in iz severa ga bodo vznemirile, zato bo šel naprej z veliko razjarjenostjo, da uniči in popolnoma odpravi mnoge.',
        45: 'Zasadil bo šotorska svetišča svoje palače med morjem in veličastno sveto goro, vendar bo prišel do svojega konca in nihče mu ne bo pomagal.',
    },
    12: {
        1: 'Ob tistem času bo vstal Mihael, veliki princ, ki stoji za otroke tvojega ljudstva in tam bo čas stiske, tak, kakršnega ni bilo, odkar je bil tam narod, celó do tega istega časa. In ob tistem času bo tvoje ljudstvo osvobojeno, vsak, kdor bo najden zapisan v knjigi.',
        2: 'Mnogi izmed teh, ki spijo v prahu zemlje, se bodo zbudili, nekateri za večno življenje, nekateri pa za sramoto in večno zaničevanje.',
        3: 'Tisti, ki so modri, bodo svetili kakor sijaj nebesnega svoda in tisti, ki mnoge obračajo k pravičnosti, [bodo] kakor zvezde na veke vekov.',
        4: '§ Toda ti, oh Daniel, zakleni besede in zapečati knjigo, celó do časa konca. Mnogi bodo tekali sem ter tja in spoznanje se bo povečalo.«',
        5: 'Potem sem jaz, Daniel, pogledal in glej tam sta stala druga dva, eden na tej strani rečnega brega, drugi pa na drugi strani rečnega brega.',
        6: 'In eden je rekel možu, oblečenemu v lan, ki je bil na vodah reke: »Doklej bo to do konca teh čudežev?«',
        7: 'Slišal sem moža, oblečenega v lan, ki je bil na vodah reke, ko je držal svojo desno roko in svojo levo roko k nebu in prisegel pri njem, ki živi na veke, da bo to za čas, [dva] časa in polovico, in ko bo dovršil, da razkropi moč svetega ljudstva, se bodo vse te stvari končale.',
        8: 'Slišal sem, toda nisem razumel. Potem sem rekel: »Oh moj Gospod, kakšen bo konec teh stvari?«',
        9: 'Rekel je: »Pojdi svojo pot, Daniel, kajti besede so zaklenjene in zapečatene do časa konca.',
        10: 'Mnogi bodo očiščeni, pobeljeni in preizkušeni, toda zlobni bodo delali zlobno in nihče izmed zlobnih ne bo razumel, toda modri bodo razumeli.',
        11: 'Od časa, ko bo dnevno žrtvovanje odvzeto in postavljena ogabnost, ki dela opustošenje, bo tisoč dvesto devetdeset dni.',
        12: 'Blagoslovljen je kdor čaka in prihaja k tisoč tristo petintridesetim dnem.',
        13: 'Toda ti pojdi svojo pot, dokler ne bo konec, kajti počival boš in stal v svojem deležu ob koncu dni.«',
    },
}
